SELECT COUNT(1) FROM user
status = #{status}
AND
role = #{role}
AND
( user_id LIKE CONCAT('%', #{keyword}, '%') OR username LIKE CONCAT('%', #{keyword}, '%') OR nickname LIKE CONCAT('%', #{keyword}, '%') OR phone LIKE CONCAT('%', #{keyword}, '%') OR email LIKE CONCAT('%', #{keyword}, '%') )

SELECT id, user_id AS userId, username, nickname, phone, email, avatar_url AS avatarUrl, status, role, create_time AS createTime, update_time AS updateTime FROM user
status = #{status}
AND
role = #{role}
AND
( user_id LIKE CONCAT('%', #{keyword}, '%') OR username LIKE CONCAT('%', #{keyword}, '%') OR nickname LIKE CONCAT('%', #{keyword}, '%') OR phone LIKE CONCAT('%', #{keyword}, '%') OR email LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY create_time DESC LIMIT #{size} OFFSET #{offset}
